mapper.select:
SELECT c.id, c.course_name, c.description, c.course_type, c.semester, c.location, c.teacher_id, t.real_name as teacher_name, c.assistant_teacher_ids, c.cover_image_url, c.status, c.create_time, c.update_time FROM mg_course c LEFT JOIN mg_teacher t ON c.teacher_id = t.id WHERE c.is_deleted = 0 AND t.is_deleted = 0
AND c.course_name LIKE CONCAT('%', #{courseName}, '%')
AND c.course_type = #{courseType}
AND c.semester = #{semester}
AND c.teacher_id = #{teacherId}
AND c.status = #{status}
ORDER BY c.create_time DESC
